// Build approval rows for each angle + 1 reject placeholder, store in Supabase, send single Telegram message with inline keyboard
const SUPA_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/approvals';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const BOT_TOKEN = '{{TELEGRAM_BOT_TOKEN}}';
const CHAT_ID = '6773796504';
const TARGET_WEBHOOK = 'https://krishraja10101.app.n8n.cloud/webhook/content-distribute-linkedin';

const response = $json.content && $json.content[0] ? $json.content[0].text : '';
const weekOf = $('Process Angles').first().json.week_of;
const angles = $('Process Angles').first().json.angles || [];

// Build message text
let message = '\u270d\ufe0f *Content Angles \u2014 Week of ' + weekOf + '*\n' +
  'Agatha picks (' + angles.length + ' angles):\n\n' +
  response;

// Build inline keyboard rows and approval row data
const keyboard = [[]];
const approvalRows = [];
for (let i = 0; i < Math.min(angles.length, 2); i++) {
  const label = i === 0 ? 'A' : 'B';
  const draftId = weekOf + '-' + label;
  const angle = angles[i] || {};
  keyboard[0].push({ text: 'Approve ' + label, callback_data: 'approve|' + draftId });
  approvalRows.push({
    source_workflow: 'Content Angle Approval',
    source_workflow_id: 'NgVcpJ7PO7sTYvm9',
    draft_id: draftId,
    title: 'Content Angle ' + label + ' for Week of ' + weekOf,
    summary: (angle.title || angle.hook || 'LinkedIn post draft').toString().slice(0, 400),
    agent_name: 'Cleo',
    payload: {
      krish_approved: true,
      approved_session: draftId,
      text: ((angle.hook || '') + '\n\n' + (angle.angle || '')).trim(),
      author_urn: 'krish-raja'
    },
    target_workflow: 'LinkedIn Distribution',
    target_webhook_url: TARGET_WEBHOOK,
    status: 'pending'
  });
}
keyboard.push([{ text: 'None this week', callback_data: 'reject|' + weekOf + '-NONE' }]);
approvalRows.push({
  source_workflow: 'Content Angle Approval',
  source_workflow_id: 'NgVcpJ7PO7sTYvm9',
  draft_id: weekOf + '-NONE',
  title: 'Skip all angles for Week of ' + weekOf,
  summary: 'Krish chose to skip this week',
  agent_name: 'Cleo',
  payload: {},
  target_workflow: 'LinkedIn Distribution',
  target_webhook_url: TARGET_WEBHOOK,
  status: 'pending'
});

// Insert approval rows
const createdRows = [];
for (const row of approvalRows) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: SUPA_URL,
      headers: {
        apikey: SUPA_KEY,
        Authorization: 'Bearer ' + SUPA_KEY,
        'Content-Type': 'application/json',
        Prefer: 'return=representation'
      },
      body: row,
      json: true
    });
    createdRows.push(Array.isArray(resp) ? resp[0] : resp);
  } catch (e) {
    createdRows.push({ error: String(e), draft_id: row.draft_id });
  }
}

// Send single Telegram message with inline keyboard
let messageId = null;
let tgError = null;
try {
  const tgResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage',
    headers: { 'Content-Type': 'application/json' },
    body: {
      chat_id: CHAT_ID,
      text: message,
      parse_mode: 'Markdown',
      reply_markup: { inline_keyboard: keyboard }
    },
    json: true
  });
  messageId = tgResp && tgResp.result ? tgResp.result.message_id : null;
} catch (e) {
  tgError = String(e);
}

// Store telegram_message_id back to each row
if (messageId) {
  for (const row of createdRows) {
    if (!row || !row.id) continue;
    try {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: SUPA_URL + '?id=eq.' + row.id,
        headers: {
          apikey: SUPA_KEY,
          Authorization: 'Bearer ' + SUPA_KEY,
          'Content-Type': 'application/json'
        },
        body: { telegram_message_id: String(messageId) },
        json: true
      });
    } catch (e) {
      // swallow, keep going
    }
  }
}

return [{
  json: {
    success: !tgError,
    message_id: messageId,
    approvals_created: createdRows.filter(r => r && r.id).length,
    week_of: weekOf,
    tg_error: tgError
  }
}];

// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}

let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const sweepData = $('Cleo Newsletter Sweep').first()?.json || {};
const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'agatha',
  duration_ms: duration,
  api_calls: (sweepData.api_calls || 0) + 2,
  cost_usd: (sweepData.cost_usd || 0),
  outcome: $input.first()?.json?.outcome || 'completed',
  outcome_count: $input.first()?.json?.result_count || 0,
  quality_score: null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log', enrichment_used: (sweepData.newsletter_themes || []).length > 0 })
};

await __httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
    'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];

// Gemini fallback body, built from the prompt node rather than the error item.
//
// The previous auto-inserted version read `src.anthropic_body` off the error
// branch item. Every workflow keys its request differently (anthropicBody,
// claudeBody, extract_body, assembly_body) and n8n's error output does not
// carry the input item's json anyway, so the builder produced an EMPTY prompt
// and Gemini answered a blank question. Pin the prompt node instead: it ran,
// so its output is always reachable.
const PROMPT_NODES = ["Process Angles"];

const PROMPT_KEYS = ['prompt', 'promptText', 'user_prompt', 'text'];

// A request body under any key: anthropic_body, anthropicBody, claudeBody,
// extract_body, assembly_body. Shape is what identifies it, not the name.
function findBody(src) {
  if (!src || typeof src !== 'object') return null;
  for (const key of Object.keys(src)) {
    let v = src[key];
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { continue; } }
    if (v && typeof v === 'object' && Array.isArray(v.messages)) return v;
  }
  return null;
}

// Or a bare prompt string, for the nodes that inline the body in the HTTP node
// and pass only the text.
function findPrompt(src) {
  if (!src || typeof src !== 'object') return null;
  for (const key of PROMPT_KEYS) {
    if (typeof src[key] === 'string' && src[key].trim()) return src[key];
  }
  return null;
}

const sources = [];
for (const nodeName of PROMPT_NODES) {
  try { sources.push($(nodeName).first().json || {}); } catch (e) { /* did not run */ }
}
try { sources.push($input.first().json || {}); } catch (e) { /* no input */ }

let body = null;
let bare = null;
for (const src of sources) {
  if (!body) body = findBody(src);
  if (!bare) bare = findPrompt(src);
}

const messages = body && Array.isArray(body.messages) ? body.messages : [];
const maxTokens = (body && body.max_tokens) || 1024;
const systemPrompt = (body && body.system) || null;

let promptText = '';
if (systemPrompt) promptText += (typeof systemPrompt === 'string' ? systemPrompt : JSON.stringify(systemPrompt)) + '\n\n';
for (const m of messages) {
  const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
  promptText += (m.role === 'user' ? content : '[assistant]: ' + content) + '\n\n';
}
promptText = promptText.trim();
if (!promptText && bare) promptText = bare.trim();

// A fallback that cannot see the prompt must say so rather than ask Gemini
// nothing and pass the answer off as an answer.
if (!promptText) {
  return [{ json: { _llm_error: 'gemini_fallback_prompt_missing', _error_source: 'fallback-builder', gemini_body: null } }];
}

return [{ json: {
  gemini_body: {
    contents: [{ parts: [{ text: promptText }] }],
    generationConfig: { maxOutputTokens: maxTokens, temperature: 0.6 }
  }
} }];

// Build identity prepend from Agent Brief + Voice Rules + Agent Plan
const briefRaw = $('Load Agatha Brief').first().json;
const voiceRaw = $('Load Voice Rules').first().json;
const planRaw  = $('Load Agatha Plan').first().json;

const briefArr = Array.isArray(briefRaw) ? briefRaw : (briefRaw.data || [briefRaw]);
const voiceArr = Array.isArray(voiceRaw) ? voiceRaw : (voiceRaw.data || [voiceRaw]);
const planArr  = Array.isArray(planRaw)  ? planRaw  : (planRaw.data  || [planRaw]);

const brief = briefArr[0]?.brief_content || '';
const voice = voiceArr[0]?.value || 'Write as Krish Raja. Direct, casual, no fluff. No em dashes. Short paragraphs. Max 120 words outbound.';
const plan  = planArr[0] || {};

const STALE_HOURS = 72;
let plan_stale = false;
if (!plan.last_rendered_at) {
  plan_stale = true;
} else {
  const ageHours = (Date.now() - new Date(plan.last_rendered_at).getTime()) / 3600000;
  plan_stale = ageHours > STALE_HOURS;
}

const planBlock = (plan.current_phase || plan.objective) ? (
  'CURRENT PLAN:\n' +
  (plan.current_phase  ? `Phase: ${plan.current_phase}\n` : '') +
  (plan.objective      ? `Objective: ${plan.objective}\n` : '') +
  (plan.next_milestone ? `Next milestone: ${plan.next_milestone}\n` : '') +
  (plan.blockers       ? `Blockers: ${plan.blockers}\n` : '') +
  (plan.doc_link       ? `Plan doc: ${plan.doc_link}\n` : '') +
  (plan.status         ? `Status: ${plan.status}\n` : '') +
  '\n'
) : '';

const identity_prepend =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n' : '') +
  planBlock +
  'VOICE RULES:\n' + voice + '\n\n';

const items = $input.all();
return items.map(item => ({
  json: { ...item.json, identity_prepend, plan_stale }
}));

const GEMINI_MODEL = "gemini-2.5-flash";
// Gemini answered. Put it in the shape the rest of this workflow parses.
//
// Downstream nodes read Anthropic's `content[0].text`. Gemini returns
// `candidates[0].content.parts[0].text`, so without this the fallback "works",
// the parse finds nothing, and the run completes with empty output and no
// alert. The fallback node also runs with neverError, so a Gemini 4xx arrives
// here as a success item carrying an `error` object: that is a failure and is
// stamped as one, not passed on as content.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};

  if (Array.isArray(j.content)) { out.push({ json: j }); continue; }

  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const parts = cand && cand.content && Array.isArray(cand.content.parts) ? cand.content.parts : [];
  const text = parts.map(p => (p && typeof p.text === 'string') ? p.text : '').join('').trim();

  if (!text) {
    const msg = (j.error && (j.error.message || JSON.stringify(j.error)))
      || j._llm_error
      || (cand && cand.finishReason ? 'gemini_finish_' + cand.finishReason : 'gemini_empty_response');
    out.push({ json: { content: [], usage: {}, _llm_provider: 'gemini', _error_source: 'both-providers', _llm_error: String(msg).slice(0, 400) } });
    continue;
  }

  const usage = j.usageMetadata || {};
  out.push({ json: {
    content: [{ type: 'text', text: text }],
    usage: { input_tokens: usage.promptTokenCount || 0, output_tokens: usage.candidatesTokenCount || 0 },
    model: GEMINI_MODEL,
    _llm_provider: 'gemini',
    _degraded: true
  } });
}
return out;
